int validate_perf_event(struct pmu_hw_events *hw_events, struct perf_event *event) {
    if (event->pmu == NULL && event->attr.type == PERF_TYPE_SOFTWARE)
        return 1;

    if (event->pmu != event->group_leader->pmu || event->state < PERF_EVENT_STATE_OFF)
        return 0;

    if (event->state == PERF_EVENT_STATE_OFF && !(event->hw.config & ARM_PMU_CONFIG_ENABLE_ON_EXEC))
