int validate_perf_event(struct pmu_hw_events *hw_events, struct perf_event *event) {
    if (event->attr.type == PERF_TYPE_SOFTWARE)
        return 1;

    if (event->pmu != event->group_leader->pmu ||
        event->state < PERF_EVENT_STATE_OFF)
        return 0;

    if (event->state == PERF_EVENT_STATE_OFF && !(event->attr.enabled_on_exec))
        return 1;

    int idx = arm_pmu_event_idx(hw_events, event);
    return (idx >= 0) ? 1 : 0;
}

int validate_perf_event(struct pmu_hw_events *hw_events, struct perf_event *event) {
    if (event->pmu == NULL)
        return 1;

    if (event->state >= PERF_EVENT_STATE_OFF && event->pmu == event->group_leader->pmu) {
        if ((event->state == PERF_EVENT_STATE_OFF) && !(event->hw.flags & PERF_EVENT_FLAG_ENABLED_ON_EXEC))
            return 1;
        int idx = arm_pmu_event_index(event);
        return (idx >= 0) ? 1 : 0;
    }

    return 0;
}
